import express, { Request, Response } from 'express';
import { InMemoryOrderRepository } from './InMemoryOrderRepository';
import { InMemoryProductRepository } from './InMemoryProductRepository';
import { PlaceOrderUseCase } from '../application/PlaceOrderUseCase';
import { UpdateOrderStateUseCase } from '../application/UpdateOrderStateUseCase';
import { CancelOrderUseCase } from '../application/CancelOrderUseCase';
import { ListOrdersByStateUseCase } from '../application/ListOrdersByStateUseCase';
import { GetProductStockUseCase } from '../application/GetProductStockUseCase';
import { OrderController } from './OrderController';
import { ProductController } from './ProductController';
import { Product } from '../domain/Product';

export function createServer() {
  const app = express();

  app.use(express.json());

  const orderRepository = new InMemoryOrderRepository();
  const productRepository = new InMemoryProductRepository();

  const initializeData = () => {
    productRepository.save(new Product('p1', 'Widget A', 100));
    productRepository.save(new Product('p2', 'Widget B', 50));
    productRepository.save(new Product('p3', 'Widget C', 75));
  };

  initializeData();

  const placeOrderUseCase = new PlaceOrderUseCase(orderRepository, productRepository);
  const updateOrderStateUseCase = new UpdateOrderStateUseCase(orderRepository);
  const cancelOrderUseCase = new CancelOrderUseCase(orderRepository, productRepository);
  const listOrdersByStateUseCase = new ListOrdersByStateUseCase(orderRepository, productRepository);
  const getProductStockUseCase = new GetProductStockUseCase(productRepository);

  const orderController = new OrderController(
    placeOrderUseCase,
    updateOrderStateUseCase,
    cancelOrderUseCase,
    listOrdersByStateUseCase
  );

  const productController = new ProductController(getProductStockUseCase);

  app.post('/orders', orderController.placeOrder);
  app.patch('/orders/:orderId/state', orderController.updateOrderState);
  app.delete('/orders/:orderId', orderController.cancelOrder);
  app.get('/orders', orderController.listOrdersByState);

  app.get('/products/:productId/stock', productController.getStock);
  app.get('/products/stock', productController.getAllStock);

  app.use((err: Error, req: Request, res: Response) => {
    const message = err instanceof Error ? err.message : 'Internal server error';
    res.status(500).json({ error: message });
  });

  return app;
}

export function startServer(port: number = 3000): void {
  const app = createServer();
  app.listen(port, () => {
    console.log(`Server running on port ${port}`);
  });
}

